import React from 'react';
import { useParams } from 'react-router-dom';
import './BikeDetails.css';

function BikeDetails() {
  const { bikeName } = useParams();

  const bikeDetails = {
    'Yamaha R15': {
      description: 'Yamaha R15 is a stylish sports bike with cutting-edge features.',
      img: 'https://link-to-image.jpg', // Add actual image URL here
    },
    'Royal Enfield Classic 350': {
      description: 'Royal Enfield Classic 350 is known for its vintage design and strong engine.',
      img: 'https://link-to-image.jpg',
    },
    'Honda Shine': {
      description: 'Honda Shine is a reliable commuter bike, known for its efficiency.',
      img: 'https://link-to-image.jpg',
    },
    'Scooty Zest 110': {
      description: 'Scooty Zest 110 is a compact and fuel-efficient scooter.',
      img: 'https://link-to-image.jpg',
    },
    // Add all other bike details in the same format...
  };

  const bike = bikeDetails[bikeName];

  if (!bike) {
    return <div>Bike not found!</div>;
  }

  return (
    <div className="bike-details">
      <h2>{bikeName}</h2>
      <img src={bike.img} alt={bikeName} />
      <p>{bike.description}</p>
    </div>
  );
}

export default BikeDetails;
